def get_admin1_name(clusters, admin_col_name, crs):
    # Import layer
    messagebox.showinfo('OnSSET', 'Select the admin 1 boundaries')
    admin_1 = gpd.read_file(filedialog.askopenfilename(filetypes = (("shapefile","*.shp"),("all files","*.*"))))
    
    clusters_support = clusters[['id', 'geometry']].to_crs({'init': "EPSG:4326"})
    
    # Apply spatial join 
    cluster_support_2 = gpd.sjoin(clusters_support, admin_1[["geometry", admin_col_name]], op='intersects').drop(['index_right'], axis=1)
    group_by_id = cluster_support_2.groupby(["id"]).sum().reset_index()
    clusters = pd.merge(clusters, group_by_id[['id', admin_col_name]], on='id', how = 'left')
    clusters.rename(columns = {admin_col_name:'Admin_1'}, inplace = True)
    
    print(datetime.now())
    
    #Return result
    return clusters

# %%
def spatial_join_largest_overlap(settlements_gdf, area_gdf, area_value_column, new_column_name=None):
    """
    Spatial join where each polygon in settlements_gdf is assigned the attribute value from area_gdf,
    based on the polygon in area_gdf with which it has the largest overlap.
    Preserves the original index of settlements_gdf.

    Args:
        settlements_gdf (gpd.GeoDataFrame): GeoDataFrame with smaller polygons (e.g., settlements).
        area_gdf (gpd.GeoDataFrame): GeoDataFrame with larger polygons (e.g., administrative areas).
        area_value_column (str): Column name in `area_gdf` whose value is to be assigned.
        new_column_name (str, optional): Name of the new column in settlements_gdf to hold the assigned values.
                                         If None, defaults to `area_value_column`.

    Returns:
        gpd.GeoDataFrame: `settlements_gdf` with a new column containing values from `area_gdf`.
    """

    sjoin_sig = inspect.signature(gpd.sjoin)
    join_kwargs = {'predicate': 'intersects'} if 'predicate' in sjoin_sig.parameters else {'op': 'intersects'}

    if new_column_name is None:
        new_column_name = area_value_column

    # Ensure CRS matches
    if settlements_gdf.crs != area_gdf.crs:
        area_gdf = area_gdf.to_crs(settlements_gdf.crs)

    # Store original index and make it a column for the join
    settlements_gdf_indexed = settlements_gdf.copy()
    settlements_gdf_indexed['_original_index'] = settlements_gdf_indexed.index # Save original index
    settlements_sub = settlements_gdf_indexed[['_original_index', 'geometry']] # Pass this to sjoin

    area_sub = area_gdf[[area_value_column, 'geometry']].copy()

    # Perform spatial join
    joined = gpd.sjoin(settlements_sub, area_sub, how='left', **join_kwargs)

    if joined.empty:
        settlements_gdf[new_column_name] = pd.NA
        return settlements_gdf

    def intersection_area(row):
        if pd.isna(row.index_right):
            return 0
        area_geom = area_sub.loc[row.index_right].geometry
        return row.geometry.intersection(area_geom).area

    joined['intersection_area'] = joined.apply(intersection_area, axis=1)

    # --- Start of refined selection logic ---
    # Sort within each original settlement group by intersection_area in descending order
    # This places the record with the largest overlap at the top of each group.
    sorted_joined = joined.sort_values(by=['_original_index', 'intersection_area'], ascending=[True, False])

    # Drop duplicates based on '_original_index', keeping the first one (which is now the max overlap)
    largest_overlaps_selected = sorted_joined.drop_duplicates(subset=['_original_index'], keep='first')
    # --- End of refined selection logic ---

    # Create a Series for mapping: index is _original_index, values are area_value_column
    # The index of map_series is guaranteed to be unique now.
    map_series = largest_overlaps_selected.set_index('_original_index')[area_value_column]

    # Use the original settlements_gdf.index to map values from map_series
    settlements_gdf[new_column_name] = settlements_gdf.index.map(map_series)

    return settlements_gdf

