import rasterio
from rasterio.windows import from_bounds
from rasterstats import gen_zonal_stats

def run_zonal_stats_clipped(polygons_gdf, raster_path, stats=['mean'], col_prefix=None, fill_na=None):
    """
    Calculates zonal statistics against a large raster by pre-clipping the raster data 
    into a small NumPy array, preventing MemoryErrors (47 GiB+).
    
    This function uses gen_zonal_stats (a generator) on the clipped array for memory efficiency.

    Args:
        polygons_gdf (GeoDataFrame): The polygons (buffers, zones) to analyze. 
                                     They should be in the metric CRS if buffering was applied 
                                     (e.g., EPSG:32637).
        raster_path (str): Path to the raster file (.tif).
        stats (str or list): The statistics to calculate (e.g., 'mean', 'sum', 'count').
        col_prefix (str): Prefix for the new column names (e.g., 'pop_clipped').
        fill_na (int/float/None): Value to fill NaN results with.
                                  - Set to a number (e.g., 0) to replace NaNs.
                                  - Set to None (the default) to keep NaNs.
        
    Returns:
        GeoDataFrame: The original GDF with the statistics columns attached.
    """
    
    # Work on a copy of the original GDF
    # (Note: For maximum speed in a loop, you could remove .copy() and modify in-place)
    output_gdf = polygons_gdf.copy()
    
    # Handle single string input for stats
    if isinstance(stats, str):
        stats = [stats]
    
    # 1. READ RASTER, PREPARE GEOMETRY, AND CALCULATE BOUNDS
    with rasterio.open(raster_path) as src:
        raster_crs = src.crs
        raster_nodata = src.nodata 
        
        # Reproject polygons to the raster's CRS to get the correct bounding box
        if polygons_gdf.crs != raster_crs:
            working_gdf = polygons_gdf.to_crs(raster_crs)
        else:
            working_gdf = polygons_gdf.copy()
            
        # Calculate the collective bounding box of all polygons
        clip_bounds = working_gdf.total_bounds
        
        # 2. READ ONLY THE REQUIRED DATA WINDOW
        print("Calculating raster window and reading only relevant data...")
        
        window = from_bounds(*clip_bounds, transform=src.transform)
        data = src.read(1, window=window)
        new_affine = src.window_transform(window)
        
        print(f"Data array shape read: {data.shape}")
        
    # 3. RUN ZONAL STATS ON THE SMALL NUMPY ARRAY
    print("Running zonal statistics on the clipped array...")
    
    stats_generator = gen_zonal_stats(
        working_gdf, 
        data, 
        affine=new_affine,
        stats=stats,
        all_touched=True,
        nodata=raster_nodata
    )
    
    results = list(stats_generator)

    # 4. ASSIGN RESULTS BACK
    for stat in stats:
        # Determine column name
        new_col_name = col_prefix if len(stats) == 1 and col_prefix else f"{col_prefix}_{stat}"
        
        # Determine default value
        default_value = fill_na if fill_na is not None else np.nan 
        
        # Extract values
        values = [res.get(stat, default_value) for res in results]
        
        # Assign to GDF
        output_gdf[new_col_name] = values
        
        # Handle NA filling
        if fill_na is not None:
            output_gdf[new_col_name] = output_gdf[new_col_name].fillna(fill_na)
        
        # We explicitly force float64.
        output_gdf[new_col_name] = output_gdf[new_col_name].astype(float).round(1)

    return output_gdf

