def processing_lines_v2(name, admin, crs, workspace, clusters, lines_path):
    # Read lines file from the provided relative path
    lines = gpd.read_file(lines_path)

    lines_clip = gpd.clip(lines, admin)
    # Note: 'init' is deprecated in recent geopandas versions, 
    # but kept here to match your original logic. 
    # Ideally use: lines_clip.crs = "EPSG:4326"
    lines_clip.crs = {'init': 'epsg:4326'}
    lines_proj = lines_clip.to_crs({'init': crs})

    # --- CHANGE 1: Use pathlib syntax (/) and .gpkg extension ---
    proj_gpkg_path = workspace / f"{name}_proj.gpkg"
    lines_proj.to_file(proj_gpkg_path, driver='GPKG')

    # Open the newly created line GeoPackage
    line_file = fiona.open(proj_gpkg_path)
    
    # --- LOGIC FIX: Removed 'firstline = next(line)' to avoid skipping data ---

    schema = {'geometry': 'Point', 'properties': {'id': 'int'}}
    
    # --- CHANGE 2: Pathlib syntax for points output ---
    proj_points_gpkg_path = workspace / f"{name}_proj_points.gpkg"
    
    # --- CHANGE 3: Write to GPKG driver ---
    with fiona.open(proj_points_gpkg_path, "w", driver="GPKG", schema=schema) as output:
        for lines_feat in line_file:
            if lines_feat["geometry"] is not None:
                first = shape(lines_feat['geometry'])
                length = first.length
                # Create a point every 100 meters
                for distance in range(0, int(length), 100):
                    point = first.interpolate(distance)
                    output.write({
                        'geometry': mapping(point), 
                        'properties': {'id': 1}
                    })

    # Read back the files we just created
    lines_f = fiona.open(proj_points_gpkg_path)
    lines = gpd.read_file(proj_gpkg_path)
    
    # --- CHANGE 4: Assuming the clusters file from the previous step is now also GPKG ---
    # We use the / operator to join the path
    points = fiona.open(workspace / 'clusters_cp.gpkg')

    # Extract coordinates for KDTree
    geoms1 = [shape(feat["geometry"]) for feat in lines_f]
    s1 = [np.array((geom.xy[0][0], geom.xy[1][0])) for geom in geoms1]
    s1_arr = np.array(s1)

    geoms2 = [shape(feat["geometry"]) for feat in points]
    s2 = [np.array((geom.xy[0][0], geom.xy[1][0])) for geom in geoms2]
    s2_arr = np.array(s2)

    def do_kdtree(combined_x_y_arrays, points):
        mytree = scipy.spatial.cKDTree(combined_x_y_arrays)
        dist, indexes = mytree.query(points)
        return dist, indexes

    def vector_overlap(vec, settlementfile, column_name):
        # Drop all columns except geometry to avoid conflicts
        vec_geo = vec[['geometry']].copy()
        a = gpd.sjoin(settlementfile, vec_geo, predicate='intersects')
        a[column_name + '2'] = 0
        return a 

    results1, results2 = do_kdtree(s1_arr, s2_arr)

    z = results1.tolist()
    clusters[name+'Dist'] = z
    clusters[name+'Dist'] = clusters[name+'Dist'] / 1000

    a = vector_overlap(lines, clusters, name+'Dist')

    clusters = pd.merge(left=clusters, right=a[['id', name+'Dist2']], on='id', how='left')
    clusters.drop_duplicates(subset="id", keep="first", inplace=True)

    clusters.loc[clusters[name+'Dist2'] == 0, name+'Dist'] = 0

    del clusters[name+'Dist2']
    
    # Clean up open fiona handles
    line_file.close()
    lines_f.close()
    points.close()
    
    print(datetime.now())
    return clusters



