import geopandas as gpd
import pandas as pd
import numpy as np
import scipy.spatial

def distance_from_lines(name, admin_gdf, project_crs, settlements_gdf, lines_path):
    """
    Calculates the distance from settlements to the nearest point on a line network.
    
    Args:
        name (str): Name of the infrastructure (e.g., 'Grid', 'Roads'). Used for column naming.
        admin_gdf (GeoDataFrame): Boundary to clip the lines to.
        project_crs (str/dict): The metric CRS to use for accurate distance (e.g., 'EPSG:32738').
        settlements_gdf (GeoDataFrame): The settlements points (polygons or points).
        lines_path (str/Path): File path to the lines shapefile/gpkg.
        
    Returns:
        GeoDataFrame: The settlements GDF with a new column '{name}Dist' (in km).
    """
    start_time = datetime.now()
    print(f"--- Starting analysis for {name} at {start_time} ---")

    # ---------------------------------------------------------
    # 1. PREPARE SETTLEMENTS (Formerly 'preparing_for_vectors')
    # ---------------------------------------------------------
    print(f"Preparing settlements...")
    # Work on a copy to protect the original variable
    clusters = settlements_gdf.copy()
    
    # Ensure settlements are in the project CRS
    if clusters.crs != project_crs:
        clusters = clusters.to_crs(project_crs)
    
    # If settlements are polygons, convert to centroid points for distance calc
    # (We assume "geometry" is the active geometry column)
    if clusters.geom_type.iloc[0] == 'Polygon' or clusters.geom_type.iloc[0] == 'MultiPolygon':
        clusters['centroid_geom'] = clusters.geometry.centroid
    else:
        clusters['centroid_geom'] = clusters.geometry

    # ---------------------------------------------------------
    # 2. PREPARE LINES
    # ---------------------------------------------------------
    print(f"Reading and processing lines...")
    try:
        lines = gpd.read_file(lines_path)
    except Exception as e:
        print(f"Error reading lines file: {e}")
        return None

    # Standardize CRS first (faster clipping if CRS matches)
    if lines.crs != admin_gdf.crs:
        lines = lines.to_crs(admin_gdf.crs)

    # Clip lines to the admin boundary to reduce dataset size
    lines_clip = gpd.clip(lines, admin_gdf)
    
    # Project to metric CRS for accurate distance measurement
    lines_clip = lines_clip.to_crs(project_crs)

    if lines_clip.empty:
        print(f"Warning: No {name} lines found within the admin boundary.")
        clusters[f'{name}Dist'] = np.nan
        return clusters

    # ---------------------------------------------------------
    # 3. GENERATE REFERENCE POINTS (Every 100m along lines)
    # ---------------------------------------------------------
    print(f"Discretizing lines into points (100m intervals)...")
    
    # We use a list to collect coordinates (x, y)
    line_coords = []
    
    for geom in lines_clip.geometry:
        if geom is not None and not geom.is_empty:
            length = geom.length
            # Create distances: 0, 100, 200...
            distances = np.arange(0, length, 100)
            
            # Interpolate allows us to find a point at specific distance
            # This list comprehension is faster than a standard loop
            points = [geom.interpolate(d) for d in distances]
            
            # We only need raw coordinates for KDTree, not Point objects
            line_coords.extend([(p.x, p.y) for p in points])

    if not line_coords:
        print("Lines exist but were too short to generate points.")
        clusters[f'{name}Dist'] = np.nan
        return clusters

    # Convert to numpy array for Scipy
    s1_arr = np.array(line_coords)

    # ---------------------------------------------------------
    # 4. KDTREE NEAREST NEIGHBOR CALCULATION
    # ---------------------------------------------------------
    print(f"Running KDTree algorithm...")
    
    # Prepare settlement coordinates
    s2_arr = np.column_stack((clusters['centroid_geom'].x, clusters['centroid_geom'].y))
    
    # Build Tree on the line points
    mytree = scipy.spatial.cKDTree(s1_arr)
    
    # Query: Find the nearest line point for every settlement
    # k=1 returns the distance to the single nearest neighbor
    dist, indexes = mytree.query(s2_arr, k=1)
    
    # Assign result (convert meters to km)
    clusters[f'{name}Dist'] = dist / 1000

    # ---------------------------------------------------------
    # 5. EXACT OVERLAP CHECK (Correction)
    # ---------------------------------------------------------
    # KDTree is approximate based on the 100m points. 
    # If a settlement is sitting exactly on a line but between our 100m dots, 
    # KDTree might say it is 40m away. We want it to be 0.
    
    print("Checking for exact physical overlaps...")
    
    # Create a temporary GDF for the spatial join (using centroids)
    centroids_gdf = gpd.GeoDataFrame(
        clusters[['id']], 
        geometry=clusters['centroid_geom'], 
        crs=project_crs
    )
    
    # Simplify lines to just geometry for speed
    lines_geo = lines_clip[['geometry']]
    
    # Spatial join: Which centroids intersect with the lines?
    # predicate='dwithin' or buffering is usually safer than 'intersects' for lines vs points,
    # but based on your previous code, we will stick to 'intersects' or a tiny buffer.
    # To mimic your original logic effectively:
    
    # Buffer lines slightly (e.g., 1 meter) to catch points "on" the line
    # lines_geo_buffered = lines_geo.copy()
    # lines_geo_buffered['geometry'] = lines_geo.buffer(1) 
    
    join_result = gpd.sjoin(centroids_gdf, lines_geo, predicate='intersects', how='inner')
    
    # Get IDs of touching settlements
    touching_ids = join_result['id'].unique()
    
    # Force distance to 0
    clusters.loc[clusters['id'].isin(touching_ids), f'{name}Dist'] = 0

    # ---------------------------------------------------------
    # CLEANUP
    # ---------------------------------------------------------
    # Remove the temporary centroid column used for calculation
    if 'centroid_geom' in clusters.columns:
        del clusters['centroid_geom']

    end_time = datetime.now()
    print(f"--- Finished {name}. Duration: {end_time - start_time} ---")
    
    return clusters


import geopandas as gpd
import pandas as pd
import numpy as np
import scipy.spatial

def distance_from_points(name, admin_gdf, project_crs, settlements_gdf, points_path):
    """
    Calculates the distance from settlements to the nearest destination point (e.g., Schools, Hospitals).
    
    Args:
        name (str): Name of the infrastructure (e.g., 'Health', 'Edu'). Used for column naming.
        admin_gdf (GeoDataFrame): Boundary to clip the destination points to.
        project_crs (str/dict): The metric CRS to use for accurate distance.
        settlements_gdf (GeoDataFrame): The settlements (origins).
        points_path (str/Path): File path to the destination points shapefile/gpkg.
        
    Returns:
        GeoDataFrame: The settlements GDF with a new column '{name}Dist' (in km).
    """
    start_time = datetime.now()
    print(f"--- Starting Point Analysis for {name} at {start_time} ---")

    # ---------------------------------------------------------
    # 1. PREPARE SETTLEMENTS
    # ---------------------------------------------------------
    # Work on a copy
    clusters = settlements_gdf.copy()
    
    # Ensure settlements are in the project CRS
    if clusters.crs != project_crs:
        clusters = clusters.to_crs(project_crs)
    
    # Calculate centroids if polygons
    if clusters.geom_type.iloc[0] == 'Polygon' or clusters.geom_type.iloc[0] == 'MultiPolygon':
        clusters['centroid_geom'] = clusters.geometry.centroid
    else:
        clusters['centroid_geom'] = clusters.geometry

    # ---------------------------------------------------------
    # 2. PREPARE DESTINATION POINTS
    # ---------------------------------------------------------
    print(f"Reading destination points...")
    try:
        dest_points = gpd.read_file(points_path)
    except Exception as e:
        print(f"Error reading points file: {e}")
        return None

    # Standardize CRS
    if dest_points.crs != admin_gdf.crs:
        dest_points = dest_points.to_crs(admin_gdf.crs)

    # Clip to admin boundary to reduce noise/size
    dest_points_clip = gpd.clip(dest_points, admin_gdf)
    
    # Project to metric CRS
    dest_points_clip = dest_points_clip.to_crs(project_crs)

    if dest_points_clip.empty:
        print(f"Warning: No {name} points found within the admin boundary.")
        clusters[f'{name}Dist'] = np.nan
        # Clean up temp column
        if 'centroid_geom' in clusters.columns:
            del clusters['centroid_geom']
        return clusters

    # ---------------------------------------------------------
    # 3. KDTREE CALCULATION
    # ---------------------------------------------------------
    print(f"Running KDTree algorithm...")
    
    # EXTRACT COORDINATES (The fast way)
    # 1. Destination Array (The Tree)
    # We use column_stack to get a (N, 2) array of X, Y
    s1_arr = np.column_stack((dest_points_clip.geometry.x, dest_points_clip.geometry.y))
    
    # 2. Origin Array (The Query)
    s2_arr = np.column_stack((clusters['centroid_geom'].x, clusters['centroid_geom'].y))
    
    # Build Tree
    mytree = scipy.spatial.cKDTree(s1_arr)
    
    # Query Tree
    # k=1 returns distance to the single nearest neighbor
    dist, indexes = mytree.query(s2_arr, k=1)
    
    # Assign result (convert meters to km)
    clusters[f'{name}Dist'] = dist / 1000

    # ---------------------------------------------------------
    # CLEANUP
    # ---------------------------------------------------------
    if 'centroid_geom' in clusters.columns:
        del clusters['centroid_geom']

    end_time = datetime.now()
    print(f"--- Finished {name}. Duration: {end_time - start_time} ---")
    
    return clusters
