# New function to calculate Dwb (area of permanent water within 10 km buffer)
import geopandas as gpd
import rasterio
import rasterio.mask
from shapely.geometry import mapping
import pyproj
import numpy as np

def calculate_raster_overlap_area_ha(raster_path, geodf, raster_crs, projected_crs, value_to_check=3, area_col='overlap_area_ha'):
    """
    Calculates the overlap area (in hectares) of raster pixels with a specific value inside polygons of a GeoDataFrame.

    Parameters:
    - raster_path: file path to input raster
    - geodf: GeoDataFrame with polygons (in any CRS, will be projected to projected_crs for area calculation)
    - raster_crs: CRS string or dict of raster coordinate system (e.g., 'EPSG:4326')
    - projected_crs: CRS string or dict for projected CRS to calculate accurate areas (e.g., UTM)
    - value_to_check: raster pixel value to count/consider as overlap, default 3 to match your raster pixels of interest
    - area_col: name of new column to add to geodf with computed overlap areas in hectares.

    Returns:
    - GeoDataFrame copy with area_col containing overlap area in hectares per polygon
    """

    # Copy GeoDataFrame to avoid modifying original
    gdf = geodf.copy()

    # Open raster
    with rasterio.open(raster_path) as src:

        # Get pixel width and height in raster CRS units (e.g., degrees if raster_crs is geographic)
        pixel_width = src.transform.a
        pixel_height = -src.transform.e

        overlap_areas = []

        # Prepare transformer from raster CRS to projected CRS for pixel size calculation
        transformer = pyproj.Transformer.from_crs(raster_crs, projected_crs, always_xy=True)

        for geom in gdf.geometry:

            # Re-project polygon to projected CRS to get accurate area measurement
            g_proj = gpd.GeoSeries([geom], crs=geodf.crs).to_crs(projected_crs).iloc[0]

            # Calculate pixel area in projected CRS by transforming pixel bounds
            lon_min = geom.bounds[0]
            lat_max = geom.bounds[3]
            lon_max = lon_min + pixel_width
            lat_min = lat_max - pixel_height

            # Transform pixel corners to projected CRS
            x1, y1 = transformer.transform(lon_min, lat_max)
            x2, y2 = transformer.transform(lon_max, lat_min)

            # Calculate pixel area in m²
            pixel_size_x = abs(x2 - x1)
            pixel_size_y = abs(y2 - y1)
            pixel_area_m2 = pixel_size_x * pixel_size_y

            # Mask raster by polygon geometry (in raster CRS)
            try:
                out_image, out_transform = rasterio.mask.mask(src, [mapping(geom)], crop=True, filled=False)
            except Exception:
                overlap_areas.append(0.0)
                continue

            masked_data = out_image[0]

            # Count pixels equal to value_to_check (and not masked)
            count_pixels = np.sum(masked_data == value_to_check)

            # Convert pixel count to hectares
            area_ha = (count_pixels * pixel_area_m2) / 10000

            overlap_areas.append(area_ha)

    # Add overlap area column to GeoDataFrame and return
    gdf[area_col] = overlap_areas
    return gdf


