def masked_water_area_to_wgs84(input_raster, projected_crs, output_crs, output_path, workspace, threshold=85):
    """
    Reprojects input raster to projected CRS, reclassifies to binary water layer, 
    calculates pixel area in m², masks non-water pixels, then reprojects back to WGS84.
    
    Parameters:
    - input_raster: path to original occurrence raster
    - projected_crs: intermediate CRS for metric accuracy (e.g., UTM)
    - output_crs: final CRS to reproject output to (default = EPSG:4326)
    - outpath:  name of output directory + file (default = "water_area_m2.tif")
    - threshold: value above which pixels are considered water
    
    Returns:
    - Path to the output raster (in WGS84)
    """
    temp_output_path = os.path.join(workspace, "temp_projected_water_area.tif")
    #output_path = os.path.join(workspace, output_path)

    # --- Step 1: Reproject and classify ---
    with rasterio.open(input_raster) as src:
        transform, width, height = calculate_default_transform(
            src.crs, projected_crs, src.width, src.height, *src.bounds)

        kwargs = src.meta.copy()
        kwargs.update({
            'crs': projected_crs,
            'transform': transform,
            'width': width,
            'height': height,
            'count': 1,
            'dtype': 'float32'
        })

        # Reproject and reclassify
        reclassified = np.empty((height, width), dtype='float32')
        reproject(
            source=rasterio.band(src, 1),
            destination=reclassified,
            src_transform=src.transform,
            src_crs=src.crs,
            dst_transform=transform,
            dst_crs=projected_crs,
            resampling=Resampling.nearest
        )

        # Binary mask: 1 where water ≥ threshold
        water_mask = (reclassified >= threshold).astype('float32')

        # Calculate pixel area in m²
        pixel_width = transform.a
        pixel_height = -transform.e
        pixel_area_m2 = abs(pixel_width * pixel_height)

        # Masked area = binary * pixel area
        water_area = water_mask * pixel_area_m2

        # Save intermediate result in projected CRS
        with rasterio.open(temp_output_path, 'w', **kwargs) as dst:
            dst.write(water_area, 1)

    # --- Step 2: Reproject result back to WGS84 ---
    with rasterio.open(temp_output_path) as src:
        dst_transform, dst_width, dst_height = calculate_default_transform(
            src.crs, output_crs, src.width, src.height, *src.bounds)

        final_kwargs = src.meta.copy()
        final_kwargs.update({
            'crs': output_crs,
            'transform': dst_transform,
            'width': dst_width,
            'height': dst_height,
            'dtype': 'float32'
        })

        with rasterio.open(output_path, 'w', **final_kwargs) as dst:
            reproject(
                source=rasterio.band(src, 1),
                destination=rasterio.band(dst, 1),
                src_transform=src.transform,
                src_crs=src.crs,
                dst_transform=dst_transform,
                dst_crs=output_crs,
                resampling=Resampling.nearest
            )

    # Clean up temp file (optional)
    os.remove(temp_output_path)

    print(f"Masked water area raster was reclassified and saved as specified")
    return 

