def createVoronoi_2_robust(admin, settlements, crs_projected, crs):
    # Project admin boundary and get its geometry
    admin_gdf_prj = admin.to_crs(crs_projected)
    admin_geom = admin_gdf_prj.geometry.iloc[0]

    # Project settlements
    settles_gdf_prj = settlements.to_crs(crs_projected)
    points_list = []

    # Extract vertices of settlement polygons as Voronoi sites
    for idx, row in settles_gdf_prj.iterrows():
        polygon_uid = row['id']
        geometry = row.geometry
        polygons = [geometry] if geometry.geom_type == 'Polygon' else geometry.geoms

        for polygon in polygons:
            exterior_coords = np.array(polygon.exterior.coords)
            for coord in exterior_coords:
                points_list.append({'id': idx, 'uid': polygon_uid, 'geometry': Point(coord)})

    points_df = gpd.GeoDataFrame(points_list, crs=crs_projected)

    # Create GeoSeries of points for Voronoi generation
    all_points = gpd.GeoSeries(points_df.geometry, crs=crs_projected)

    # Generate Voronoi polygons extending to a large buffer around admin
    try:
        voronois = all_points.voronoi_polygons(extend_to=admin_geom.buffer(50000))
    except Exception as e:
        raise RuntimeError(f"Error creating Voronoi polygons: {e}")

    # Convert to GeoDataFrame and set CRS
    vor_gdf = gpd.GeoDataFrame(geometry=voronois, crs=crs_projected)
    
    # Clip Voronoi polygons to the actual admin boundary polygon
    vor_gdf = gpd.overlay(vor_gdf, gpd.GeoDataFrame(geometry=[admin_geom], crs=crs_projected), how='intersection')

    # Add unique ID for merging later
    vor_gdf['uniqueID'] = range(1, len(vor_gdf) + 1)

    # Spatial join to assign settlement IDs based on vertex points
    joined = gpd.sjoin(vor_gdf, points_df[['geometry', 'uid']], how='left', predicate='intersects').drop(columns=['index_right'])

    # Merge settlement uid back to Voronoi polygons
    result = vor_gdf.merge(joined[['uniqueID', 'uid']], on='uniqueID', how='left')

    # Dissolve Voronoi polygons by settlement uid
    result_dissolved = result.dissolve(by='uid')

    # Calculate area and convert back to original CRS
    result_dissolved["Vor_area_sq.km"] = result_dissolved.geometry.area / 10**6
    result_dissolved["Vor_area_ha"] = result_dissolved["Vor_area_sq.km"] * 100
    result_dissolved = result_dissolved.to_crs(crs)

    return result_dissolved


