import plotly.graph_objects as go
from plotly.subplots import make_subplots

def plot_histogram_map(settles_gdf, default_column, figure_title="", point_size=2.5,point_opacity=0.5):
    # Create a copy and set geometry to centroids
    centroids_gdf = settles_gdf.copy()
    centroids_gdf.geometry = centroids_gdf.geometry.centroid

    # Optional filter for variable > 0
    centroids_gdf = centroids_gdf[centroids_gdf[default_column] > 0]
    filtered_settles_gdf = settles_gdf[settles_gdf[default_column] > 0]

    # Create subplots: 1 row, 2 columns
    fig = make_subplots(
        rows=1, cols=2,
        subplot_titles=('Histogram', 'Map'),
        specs=[[{"type": "histogram"}, {"type": "scattermapbox"}]],
        horizontal_spacing=0.02
    )

    # Left plot: histogram
    fig.add_trace(
        go.Histogram(
            x=filtered_settles_gdf[default_column],
            marker_color='skyblue',
            marker_line_color='black',
            marker_line_width=1,
            opacity=1,
            name=default_column
        ),
        row=1, col=1
    )

    # Right plot: map of centroids colored by variable
    fig.add_trace(
        go.Scattermapbox(
            lat=centroids_gdf.geometry.y,
            lon=centroids_gdf.geometry.x,
            mode='markers',
            marker=go.scattermapbox.Marker(
                size=point_size,
                color=centroids_gdf[default_column],
                colorscale='bluered_r',
                colorbar=dict(
                    title=default_column,
                    orientation='h',
                    y=-0.05,
                    x=0.5,
                    xanchor='center',
                    yanchor='top',
                    len=0.8,
                    thickness=10
                ),
                cmin=centroids_gdf[default_column].min(),
                cmax=centroids_gdf[default_column].max(),
                opacity=point_opacity
            ),
            hovertemplate=f'<b>{default_column}</b>: %{{marker.color:.3f}}<br>Lat: %{{lat:.3f}}<br>Lon: %{{lon:.3f}}<extra></extra>',
            hoverinfo='text',
            name='points'
        ),
        row=1, col=2
    )

    # Update histogram axis labels
    fig.update_yaxes(title_text="Frequency", row=1, col=1)

    # Update map layout
    fig.update_layout(
        height=600,
        showlegend=False,
        title_text=figure_title,
        mapbox=dict(
            style="open-street-map",
            center=dict(
                lat=centroids_gdf.geometry.y.mean(),
                lon=centroids_gdf.geometry.x.mean()
            ),
            zoom=4
        ),
        hovermode='closest'
    )

    fig.show(config={'scrollZoom': True})
    return fig


import socket

def find_available_port(default_port=8050):
    port = default_port
    while port < 65535: # Iterate up to the maximum port number
        try:
            # Try to bind to the port
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.bind(('127.0.0.1', port))
            # If successful, return the port
            return port
        except OSError:
            # If the address is already in use, try the next port
            port += 1
    raise RuntimeError("Could not find an available port.")


from pathlib import Path
from typing import Union, List, Optional

def get_single_input_file_path(
    input_directory_path: Union[str, Path],
    allowed_extensions: Optional[List[str]] = None
) -> Path:
    """
    Checks the specified directory for exactly one file matching the allowed extensions 
    and returns its path.

    Args:
        input_directory_path: The full Path object or string path to the directory 
                              containing the input file(s).
        allowed_extensions: A list of file extensions (e.g., ['.shp', '.gpkg']) 
                            to look for. If None, it looks for ANY single file. 
                            The extension check is case-insensitive.

    Returns:
        The absolute Path object of the single matching file found in the directory.

    Raises:
        FileNotFoundError: If the specified path is not a directory or no matching files are found.
        ValueError: If more than one matching file is found in the directory.
    """
    
    input_dir = Path(input_directory_path)

    # 1. Check for existence and verify it is a directory
    if not input_dir.is_dir():
        raise FileNotFoundError(
            f"Input directory not found or is not a directory: {input_dir}"
        )
    
    # Normalize extensions for case-insensitive comparison
    if allowed_extensions:
        # Prepend a dot if it's missing (e.g., 'shp' becomes '.shp') and make lowercase
        normalized_extensions = [
            ext if ext.startswith('.') else f'.{ext}' 
            for ext in [e.lower() for e in allowed_extensions]
        ]
        
    # 2. List and filter files
    matching_file_list = []
    for p in input_dir.iterdir():
        if p.is_file():
            # Check if an extension filter is applied
            if allowed_extensions:
                # Check if the file's extension matches one of the normalized extensions
                if p.suffix.lower() in normalized_extensions:
                    matching_file_list.append(p)
            else:
                # If no extension filter, treat it as a potential match
                matching_file_list.append(p)

    num_files = len(matching_file_list)
    
    # 3. Apply the single file logic to the filtered list
    
    if num_files == 0:
        ext_hint = f" matching extensions {allowed_extensions}" if allowed_extensions else ""
        raise FileNotFoundError(
            f"No files{ext_hint} found in the input folder: {input_dir}. "
            "Please ensure the required file is placed there."
        )
        
    elif num_files > 1:
        file_names = "\n- " + "\n- ".join([f.name for f in matching_file_list])
        raise ValueError(
            f"Multiple files ({num_files}) matching the specified criteria found in: {input_dir}.\n"
            "Please ensure **only one** file (e.g., one .shp or one .gpkg) is present for processing."
            f"Found files:{file_names}"
        )
        
    else:
        # Return the path to the single matching file found
        return matching_file_list[0]
    

#to be moved to funcs
def add_zonal_stats_to_gdf(gdf, raster_path, new_col_name, method):
    """
    Performs zonal statistics on a GeoDataFrame using a raster and adds
    the resulting statistic as a new column to the GeoDataFrame.

    Parameters:
    - gdf (gpd.GeoDataFrame): The input GeoDataFrame containing polygons.
    - raster_path (str): The file path to the raster.
    - new_col_name (str): The name for the new column to be added to the gdf.
    - method (str): The statistic method to calculate (e.g., 'mean', 'max', 'sum').

    Returns:
    - gpd.GeoDataFrame: The original GeoDataFrame with the new statistics
                        column added.
    """
    # Perform extraction and get a list of dictionaries with stats
    # If raster_path is invalid, rasterio.open will raise a FileNotFoundError
    with rasterio.open(raster_path) as raster:
        stats = zonal_stats(
            gdf,
            raster.name,
            stats=method,
            all_touched=True
        )
    
    # Extract the values into a list and add them to a new column.
    # The order of stats matches the order of features in the gdf.
    # Use a try-except block to handle cases where the statistic might be missing
    # for a feature.
    try:
        gdf[new_col_name] = [s[method] for s in stats]
    except KeyError:
        print(f"Warning: The statistic '{method}' was not found in the zonal stats output. "
              "The new column will not be created.")
    
    return gdf